const items = $input.all();
const out = [];
for (const i of items) {
  const j = i.json || {};
  const url = String(j.link || j.url || j.guid || '').trim();
  if (!url.startsWith('http')) continue;
  out.push({
    json: {
      title: String(j.title || '').slice(0, 240),
      url,
      published_at: String(j.pubDate || j.isoDate || new Date().toISOString()),
      source: 'cointelegraph-rss',
    }
  });
  if (out.length >= 2) break;
}
return out;

const POS = ['rally','surge','bullish','gains','gain','rises','rise','soar','jump','jumps','record','high','recover','recovery','boom','growth','profit','profits','strong','positive','upward','breakout','outperform','beat','beats','upgrade','buy','hawkish','stimulus','approval','inflow','etf','adopt','adoption'];
const NEG = ['crash','drop','drops','bearish','loss','losses','fall','falls','plunge','plunges','sink','sinks','decline','declines','fear','risk','warn','warning','sell','downgrade','weak','negative','slump','tumble','tumbles','panic','collapse','recession','hack','lawsuit','outflow','ban','fraud','default'];
const SYMBOLS = [
  {sym:'BTCUSDT', keys:['bitcoin','btc']},
  {sym:'ETHUSDT', keys:['ethereum','eth']},
  {sym:'SOLUSDT', keys:['solana','sol']},
  {sym:'XRPUSDT', keys:['ripple','xrp']},
  {sym:'BNBUSDT', keys:['bnb','binance coin']},
];

function scoreText(t) {
  const w = String(t || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  let p = 0, n = 0;
  for (const x of w) {
    if (POS.includes(x)) p++;
    if (NEG.includes(x)) n++;
  }
  const tot = p + n;
  if (!tot) return {sentiment_score: 0, impact_score: 0.2};
  const s = (p - n) / tot;
  const impact = Math.min(1, 0.2 + tot / 14);
  return {
    sentiment_score: Math.round(Math.max(-1, Math.min(1, s)) * 1000) / 1000,
    impact_score: Math.round(impact * 1000) / 1000,
  };
}

function extractFetchText(j) {
  const data = (j && j.data && typeof j.data === 'object') ? j.data : (j || {});
  const chunks = [
    data.content, data.markdown, data.text, data.html,
    j.content, j.markdown, j.text,
    data.body, j.body,
  ];
  for (const c of chunks) {
    if (typeof c === 'string' && c.trim().length > 40) return c.trim().slice(0, 8000);
  }
  try {
    const s = JSON.stringify(j);
    return s.length > 40 ? s.slice(0, 4000) : '';
  } catch (e) {
    return '';
  }
}

const fetchItems = $input.all();
const prevItems = $('Limit News URLs').all();
const out = [];
for (let i = 0; i < fetchItems.length; i++) {
  const j = fetchItems[i].json || {};
  const prev = ((prevItems[i] || prevItems[0] || {}).json) || {};
  const text = extractFetchText(j);
  const title = prev.title || ((j.data && j.data.metadata && j.data.metadata.title) || j.title || '');
  if (!text || text.length < 40) continue;
  const blob = (title + ' ' + text).toLowerCase();
  let matched = SYMBOLS.filter(s => s.keys.some(k => blob.includes(k))).map(s => s.sym);
  if (!matched.length) matched = ['BTCUSDT'];
  matched = matched.slice(0, 3);
  const scored = scoreText(title + ' ' + text);
  const headline = String(title || prev.url || 'article').slice(0, 180);
  out.push({
    json: {
      title: String(title || '').slice(0, 500),
      content: text,
      source: prev.source || 'omniroute-firecrawl-fetch',
      url: prev.url,
      published_at: String(prev.published_at || new Date().toISOString()),
      sentiment: scored.sentiment_score,
      symbols: matched,
      embed_text: (String(title || '') + '\n' + text).slice(0, 8000),
      sentiment_score: scored.sentiment_score,
      impact_score: scored.impact_score,
      time_horizon: 'short',
      topics: headline,
    }
  });
}
return out;

const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const symbols = Array.isArray(j.symbols) && j.symbols.length ? j.symbols : ['BTCUSDT'];
  const headline = String(j.topics || j.title || '').slice(0, 180);
  for (const sym of symbols.slice(0, 3)) {
    out.push({
      json: {
        symbol: String(sym),
        sentiment_score: Number(j.sentiment_score || 0),
        impact_score: Number(j.impact_score || 0),
        source: j.source || 'omniroute-firecrawl-fetch',
        time_horizon: j.time_horizon || 'short',
        topics: headline,
      }
    });
  }
}
return out;

const embItems = $input.all();
const prevItems = $('Score Article Sentiment').all();
const out = [];
for (let i = 0; i < embItems.length; i++) {
  const j = embItems[i].json || {};
  const prev = ((prevItems[i] || prevItems[0] || {}).json) || {};
  let emb = [];
  const data = j.data ? j.data : j;
  if (Array.isArray(data) && data[0] && Array.isArray(data[0].embedding)) {
    emb = data[0].embedding;
  } else if (data && Array.isArray(data.data) && data.data[0] && Array.isArray(data.data[0].embedding)) {
    emb = data.data[0].embedding;
  } else if (Array.isArray(j.embedding)) {
    emb = j.embedding;
  }
  const dim = Array.isArray(emb) ? emb.length : 0;
  if (!dim) {
    out.push({ json: { archive_skipped: true, reason: 'no_embedding', embedding_dim: 0 } });
    continue;
  }
  out.push({
    json: {
      title: String(prev.title || '').slice(0, 500),
      content: String(prev.content || '').slice(0, 20000),
      source: String(prev.source || 'omniroute-firecrawl-fetch'),
      url: String(prev.url || ''),
      published_at: String(prev.published_at || new Date().toISOString()),
      sentiment: Number(prev.sentiment || 0),
      symbols: Array.isArray(prev.symbols) ? prev.symbols : [],
      embedding: emb,
      embedding_dim: dim,
    }
  });
}
return out;

const items=$input.all();
const base=items.map(i=>i.json);
return [{json:{query:'bitcoin OR ethereum OR solana OR crypto market news today', max_results:10, rss_items: base}}];

function extractHits(j) {
  const hits=[]; const pools=[];
  if (!j || typeof j !== 'object') return hits;
  if (Array.isArray(j.results)) pools.push(j.results);
  if (Array.isArray(j.data)) pools.push(j.data);
  if (j.data && Array.isArray(j.data.results)) pools.push(j.data.results);
  if (Array.isArray(j.organic)) pools.push(j.organic);
  if (Array.isArray(j.news_results)) pools.push(j.news_results);
  if (Array.isArray(j.items)) pools.push(j.items);
  for (const arr of pools) {
    for (const r of arr) {
      if (!r || typeof r !== 'object') continue;
      const title=String(r.title||r.name||'').trim();
      const url=String(r.url||r.link||r.href||'').trim();
      const snippet=String(r.snippet||r.description||r.content||'').trim().slice(0,240);
      if (url.startsWith('http')) hits.push({title,url,snippet,link:url,source:'qt-search'});
    }
  }
  return hits;
}
function safe(n){ try{return $(n).first().json||{};}catch(e){return {};} }
const seed = safe('QT Search Seed');
const rss = Array.isArray(seed.rss_items) ? seed.rss_items : [];
const seen=new Set();
const out=[];
for (const r of rss) {
  const url=String(r.link||r.url||r.guid||'').trim();
  if (!url.startsWith('http')) continue;
  const key=url.toLowerCase();
  if (seen.has(key)) continue; seen.add(key);
  out.push({ json: { ...r, link:url, url, source: r.source||'rss' } });
}
for (const name of ['Tavily Search QT','SerpAPI News QT','Jina Search QT','Firecrawl Direct QT']) {
  for (const h of extractHits(safe(name))) {
    const key=h.url.toLowerCase();
    if (seen.has(key)) continue; seen.add(key);
    out.push({ json: { title:h.title, link:h.url, url:h.url, contentSnippet:h.snippet, source:h.source } });
  }
}
// stash CMC on static for later nodes via first item meta
let market=null;
try {
  const cmc=safe('CMC Quotes QT');
  const d=cmc.data||cmc; market={};
  for (const sym of ['BTC','ETH','SOL']) {
    const row=d[sym]; if(!row) continue;
    const q=(row.quote&&row.quote.USD)||{};
    market[sym]={price:q.price, change_24h:q.percent_change_24h};
  }
  if (!Object.keys(market).length) market=null;
} catch(e) {}
if (!out.length) return [{ json: { link:'', url:'', title:'', skip:true, market } }];
out[0].json.market = market;
return out.slice(0, 12);
